#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "text_ops.h"
#include "redo_undo.h"
static Node *lineAt(TextEditor *e,int no){Node*n;int i=1;if(!e||no<1)return NULL;for(n=e->head;n&&i<no;n=n->next)i++;return n;}
static void history(TextEditor*e,OperationType op,int line,int pos,const char*text){Action a;if(!e->recordingHistory)return;a.operation=op;a.lineNumber=line;a.position=pos;a.text=(char*)text;if(pushStack(&e->undoStack,a))clearStack(&e->redoStack);}
Node *createNode(const char*s){Node*n;if(!s)return NULL;n=malloc(sizeof(*n));if(!n)return NULL;n->line=malloc(strlen(s)+1);if(!n->line){free(n);return NULL;}strcpy(n->line,s);n->prev=n->next=NULL;return n;}
int insertLineAtPosition(TextEditor*e,const char*s,int no){Node*n,*at;int total=0;if(!e||!s||no<1)return 0;for(at=e->head;at;at=at->next)total++;if(no>total+1)return 0;n=createNode(s);if(!n)return 0;at=lineAt(e,no);if(!at){n->prev=e->tail;if(e->tail)e->tail->next=n;else e->head=n;e->tail=n;}else{n->next=at;n->prev=at->prev;if(at->prev)at->prev->next=n;else e->head=n;at->prev=n;}if(!e->cursor){e->cursor=n;e->cursorLine=no;e->cursorPos=0;}else if(e->cursorLine>=no)e->cursorLine++;history(e,INSERT_LINE_ACTION,no,0,s);return 1;}
int insertLine(TextEditor*e,const char*s){int n=1;Node*p;if(!e)return 0;for(p=e->head;p;p=p->next)n++;return insertLineAtPosition(e,s,n);}
int deleteLine(TextEditor*e,int no){Node*n=lineAt(e,no);if(!n)return 0;history(e,DELETE_LINE_ACTION,no,0,n->line);if(n->prev)n->prev->next=n->next;else e->head=n->next;if(n->next)n->next->prev=n->prev;else e->tail=n->prev;if(e->cursor==n){if(n->next){e->cursor=n->next;e->cursorLine=no;}else{e->cursor=n->prev;e->cursorLine=no>1?no-1:1;}e->cursorPos=0;}else if(e->cursorLine>no)e->cursorLine--;if(!e->head){e->cursor=NULL;e->cursorLine=1;e->cursorPos=0;}else if(!e->cursor){e->cursor=e->head;e->cursorLine=1;}free(n->line);free(n);return 1;}
void displayText(TextEditor*e){Node*p;int i=1;if(!e||!e->head){puts("[Empty document]");return;}for(p=e->head;p;p=p->next)printf("%d | %s\n",i++,p->line);}
int insertCharacters(TextEditor*e,int no,int pos,const char*s){Node*n=lineAt(e,no);size_t len,add;char*b;int idx;if(!n||!s||pos<1)return 0;len=strlen(n->line);add=strlen(s);idx=pos-1;if((size_t)idx>len)return 0;b=malloc(len+add+1);if(!b)return 0;memcpy(b,n->line,idx);memcpy(b+idx,s,add);memcpy(b+idx+add,n->line+idx,len-idx+1);history(e,INSERT_ACTION,no,idx,s);free(n->line);n->line=b;if(e->cursor==n&&e->cursorPos>=idx)e->cursorPos+=(int)add;return 1;}
int deleteCharacters(TextEditor*e,int no,int pos,int count){Node*n=lineAt(e,no);size_t len,start,amt;char*del,*b;if(!n||pos<1||count<=0)return 0;len=strlen(n->line);start=(size_t)(pos-1);amt=(size_t)count;if(start>=len||amt>len-start)return 0;del=malloc(amt+1);b=malloc(len-amt+1);if(!del||!b){free(del);free(b);return 0;}memcpy(del,n->line+start,amt);del[amt]='\0';memcpy(b,n->line,start);memcpy(b+start,n->line+start+amt,len-start-amt+1);history(e,DELETE_ACTION,no,(int)start,del);free(del);free(n->line);n->line=b;if(e->cursor==n){if((size_t)e->cursorPos>=start+amt)e->cursorPos-=(int)amt;else if((size_t)e->cursorPos>start)e->cursorPos=(int)start;}return 1;}
char *copyText(TextEditor*e,int no,int pos,int count){Node*n=lineAt(e,no);size_t len,start,amt;char*c;if(!n||pos<1||count<=0)return NULL;len=strlen(n->line);start=(size_t)(pos-1);if(start>=len)return NULL;amt=(size_t)count;if(amt>len-start)amt=len-start;c=malloc(amt+1);if(!c)return NULL;memcpy(c,n->line+start,amt);c[amt]='\0';return c;}
char *cutText(TextEditor*e,int no,int pos,int count){char*c=copyText(e,no,pos,count);if(!c)return NULL;if(!deleteCharacters(e,no,pos,(int)strlen(c))){free(c);return NULL;}return c;}
int pasteText(TextEditor*e,int no,int pos,const char*s){return insertCharacters(e,no,pos,s);}
